import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.CQdbgswV.js";const g=JSON.parse('{"title":"01 核心词汇体系","description":"","frontmatter":{},"headers":[],"relativePath":"01-core-vocabulary.md","filePath":"01-core-vocabulary.md","lastUpdated":1792666721000}'),a={name:"01-core-vocabulary.md"};function s(n,t,c,i,l,h){return d(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="_01-核心词汇体系" tabindex="-1">01 核心词汇体系 <a class="header-anchor" href="#_01-核心词汇体系" aria-label="Permalink to &quot;01 核心词汇体系&quot;">​</a></h1><blockquote><p>本章目标：掌握技术英语词汇的<strong>学习方法</strong>，拿下第一批 60 个最高频词汇（三个主题组），并能拆解真实报错信息。</p></blockquote><h2 id="_1-1-场景导入-为什么背了单词书还是读不懂文档" tabindex="-1">1.1 场景导入：为什么背了单词书还是读不懂文档 <a class="header-anchor" href="#_1-1-场景导入-为什么背了单词书还是读不懂文档" aria-label="Permalink to &quot;1.1 场景导入：为什么背了单词书还是读不懂文档&quot;">​</a></h2><p>先看一段真实的文档（摘自 React 官网）：</p><blockquote><p><strong>Strict Mode</strong> enables the following development-only behaviors:</p><ul><li>Your components will <strong>re-render</strong> an extra time to find bugs caused by <strong>impure rendering</strong>.</li><li>Your components will <strong>re-run Effects</strong> an extra time to find bugs caused by missing Effect <strong>cleanup</strong>.</li></ul></blockquote><p>如果你在四级词表里背过 <code>strict</code>（严格的）、<code>render</code>（给予、表演）、<code>effect</code>（效果）、<code>cleanup</code>（大扫除），恭喜——每个词都认识，但这段话依然读不懂。因为技术语境下：</p><ul><li><code>render</code> = 渲染（组件输出 UI 的过程），不是&quot;表演&quot;；</li><li><code>Effect</code> = React 的副作用 Hook，是专有名词；</li><li><code>cleanup</code> = 组件卸载时执行的清理函数，不是&quot;大扫除&quot;。</li></ul><p><strong>结论：技术英语的核心矛盾不是词汇量，而是「日常词的技术义项」和「技术专有词汇」。</strong> 好消息是：技术文档用词高度集中——统计主流开源项目的文档，约 500 个高频词覆盖了 90% 以上的内容。这就是本章要建立的词汇体系。</p><h2 id="_1-2-方法论-三个原则" tabindex="-1">1.2 方法论：三个原则 <a class="header-anchor" href="#_1-2-方法论-三个原则" aria-label="Permalink to &quot;1.2 方法论：三个原则&quot;">​</a></h2><h3 id="原则一-词块-chunk-优先-不背孤词" tabindex="-1">原则一：词块（chunk）优先，不背孤词 <a class="header-anchor" href="#原则一-词块-chunk-优先-不背孤词" aria-label="Permalink to &quot;原则一：词块（chunk）优先，不背孤词&quot;">​</a></h3><p>不要背 <code>deprecate = 废弃</code>，要背 <code>This API is deprecated, use X instead.</code>（这个 API 已废弃，请改用 X）。词块整体记忆，读到时整句理解，不需要逐词翻译。</p><h3 id="原则二-在真实语境中记词" tabindex="-1">原则二：在真实语境中记词 <a class="header-anchor" href="#原则二-在真实语境中记词" aria-label="Permalink to &quot;原则二：在真实语境中记词&quot;">​</a></h3><p>每个词至少配一个真实语境：报错信息、文档原句、Issue 评论、Commit message。本章所有例句均取自真实场景。</p><h3 id="原则三-按主题分组-建立关联" tabindex="-1">原则三：按主题分组，建立关联 <a class="header-anchor" href="#原则三-按主题分组-建立关联" aria-label="Permalink to &quot;原则三：按主题分组，建立关联&quot;">​</a></h3><p>孤立的词容易忘，成组的词互相提示。本教程把 500 词分为四大主题组：</p><table tabindex="0"><thead><tr><th>主题组</th><th>词量</th><th>典型场景</th></tr></thead><tbody><tr><td>编程概念</td><td>~180</td><td>读官方文档、教程</td></tr><tr><td>调试报错</td><td>~120</td><td>看报错信息、Stack Overflow</td></tr><tr><td>架构设计</td><td>~80</td><td>读 RFC、设计文档</td></tr><tr><td>团队协作</td><td>~120</td><td>Issue / PR / Review / IM</td></tr></tbody></table><p>本章先拿下前三个主题组中最高频的 60 词，其余词量在后续章节随场景滚动补充。</p><h2 id="_1-3-主题组一-编程概念-20-词" tabindex="-1">1.3 主题组一：编程概念（20 词） <a class="header-anchor" href="#_1-3-主题组一-编程概念-20-词" aria-label="Permalink to &quot;1.3 主题组一：编程概念（20 词）&quot;">​</a></h2><h3 id="动词" tabindex="-1">动词 <a class="header-anchor" href="#动词" aria-label="Permalink to &quot;动词&quot;">​</a></h3><table tabindex="0"><thead><tr><th>词汇</th><th>释义</th><th>真实语料</th></tr></thead><tbody><tr><td><strong>declare</strong></td><td>声明（变量/类型）</td><td><code>Variables declared with let are block-scoped.</code>（MDN）</td></tr><tr><td><strong>assign</strong></td><td>赋值</td><td><code>You cannot assign to a constant variable.</code></td></tr><tr><td><strong>invoke / call</strong></td><td>调用（函数）</td><td><code>The callback is invoked with three arguments.</code>（MDN）</td></tr><tr><td><strong>return</strong></td><td>返回</td><td><code>The function returns a Promise.</code></td></tr><tr><td><strong>pass</strong></td><td>传入（参数）</td><td><code>Pass the event handler as a prop.</code></td></tr><tr><td><strong>instantiate</strong></td><td>实例化</td><td><code>Instantiate the client with your API key.</code></td></tr><tr><td><strong>mutate</strong></td><td>修改（原地改变数据）</td><td><code>sort() mutates the array in place.</code>（MDN）</td></tr><tr><td><strong>iterate</strong></td><td>遍历</td><td><code>Iterate over the entries of the Map.</code></td></tr></tbody></table><h3 id="名词" tabindex="-1">名词 <a class="header-anchor" href="#名词" aria-label="Permalink to &quot;名词&quot;">​</a></h3><table tabindex="0"><thead><tr><th>词汇</th><th>释义</th><th>真实语料</th></tr></thead><tbody><tr><td><strong>parameter / argument</strong></td><td>形参 / 实参</td><td><code>Parameters are the names in the definition; arguments are the values you pass in.</code>（MDN）</td></tr><tr><td><strong>variable / constant</strong></td><td>变量 / 常量</td><td><code>const declares a block-scoped constant.</code></td></tr><tr><td><strong>scope</strong></td><td>作用域</td><td><code>The variable is not accessible outside its scope.</code></td></tr><tr><td><strong>closure</strong></td><td>闭包</td><td><code>A closure gives you access to an outer function&#39;s scope.</code>（MDN）</td></tr><tr><td><strong>instance</strong></td><td>实例</td><td><code>Each instance holds its own state.</code></td></tr><tr><td><strong>expression / statement</strong></td><td>表达式 / 语句</td><td><code>An expression produces a value; a statement performs an action.</code></td></tr><tr><td><strong>literal</strong></td><td>字面量</td><td><code>A template literal is enclosed by backticks.</code>（MDN）</td></tr></tbody></table><h3 id="形容词-副词" tabindex="-1">形容词/副词 <a class="header-anchor" href="#形容词-副词" aria-label="Permalink to &quot;形容词/副词&quot;">​</a></h3><table tabindex="0"><thead><tr><th>词汇</th><th>释义</th><th>真实语料</th></tr></thead><tbody><tr><td><strong>immutable / mutable</strong></td><td>不可变 / 可变</td><td><code>Strings are immutable in JavaScript.</code></td></tr><tr><td><strong>asynchronous (async)</strong></td><td>异步</td><td><code>fetch() is an asynchronous API.</code></td></tr><tr><td><strong>synchronous (sync)</strong></td><td>同步</td><td><code>The synchronous version blocks the event loop.</code></td></tr><tr><td><strong>optional</strong></td><td>可选的</td><td><code>The options parameter is optional.</code></td></tr><tr><td><strong>required</strong></td><td>必需的</td><td><code>The first argument is required.</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">记忆钩子</p><p><code>parameter</code>（形参）与 <code>argument</code>（实参）的区别是文档常客：<strong>P</strong>arameter 是 <strong>P</strong>laceholder（占位符，定义时），<strong>A</strong>rgument 是 <strong>A</strong>ctual value（实际值，调用时）。</p></div><h2 id="_1-4-主题组二-调试报错-20-词" tabindex="-1">1.4 主题组二：调试报错（20 词） <a class="header-anchor" href="#_1-4-主题组二-调试报错-20-词" aria-label="Permalink to &quot;1.4 主题组二：调试报错（20 词）&quot;">​</a></h2><p>报错信息是程序员每天读得最多的英文。把这些词拿下，报错阅读速度立刻翻倍。</p><h3 id="报错信息高频词" tabindex="-1">报错信息高频词 <a class="header-anchor" href="#报错信息高频词" aria-label="Permalink to &quot;报错信息高频词&quot;">​</a></h3><table tabindex="0"><thead><tr><th>词汇</th><th>释义</th><th>真实语料</th></tr></thead><tbody><tr><td><strong>throw</strong></td><td>抛出（异常）</td><td><code>throw new TypeError(&#39;...&#39;)</code></td></tr><tr><td><strong>catch / handle</strong></td><td>捕获 / 处理</td><td><code>Uncaught (in promise) TypeError</code>（浏览器控制台）</td></tr><tr><td><strong>stack trace</strong></td><td>调用栈追踪</td><td><code>at Object.&lt;anonymous&gt; (/app/index.js:10:15)</code></td></tr><tr><td><strong>undefined / null</strong></td><td>未定义 / 空值</td><td><code>Cannot read properties of undefined (reading &#39;map&#39;)</code>（V8 报错）</td></tr><tr><td><strong>reference / reference error</strong></td><td>引用 / 引用错误</td><td><code>ReferenceError: x is not defined</code></td></tr><tr><td><strong>syntax error</strong></td><td>语法错误</td><td><code>SyntaxError: Unexpected token &#39;&lt;&#39;</code></td></tr><tr><td><strong>exceed</strong></td><td>超出</td><td><code>Maximum call stack size exceeded</code>（栈溢出）</td></tr><tr><td><strong>invalid</strong></td><td>无效的</td><td><code>Invalid or unexpected token</code></td></tr><tr><td><strong>missing</strong></td><td>缺失的</td><td><code>Missing semicolon.</code>（JSHint）</td></tr><tr><td><strong>expected</strong></td><td>期望的</td><td><code>Expected an assignment or function call</code></td></tr></tbody></table><h3 id="排查过程高频词" tabindex="-1">排查过程高频词 <a class="header-anchor" href="#排查过程高频词" aria-label="Permalink to &quot;排查过程高频词&quot;">​</a></h3><table tabindex="0"><thead><tr><th>词汇</th><th>释义</th><th>真实语料</th></tr></thead><tbody><tr><td><strong>reproduce (repro)</strong></td><td>复现</td><td><code>I can&#39;t reproduce this on v18.</code>（GitHub Issue）</td></tr><tr><td><strong>regression</strong></td><td>回归（旧功能被改坏）</td><td><code>This looks like a regression introduced in v2.3.</code></td></tr><tr><td><strong>workaround</strong></td><td>临时绕过方案</td><td><code>As a workaround, pin the version to 1.2.0.</code></td></tr><tr><td><strong>root cause</strong></td><td>根因</td><td><code>The root cause was a race condition.</code></td></tr><tr><td><strong>debug / troubleshoot</strong></td><td>调试 / 排障</td><td><code>See the troubleshooting guide.</code></td></tr><tr><td><strong>fix / patch</strong></td><td>修复 / 补丁</td><td><code>This patch fixes a memory leak.</code></td></tr><tr><td><strong>deprecate</strong></td><td>废弃（仍可用但将移除）</td><td><code>This method is deprecated since v3.0.</code></td></tr><tr><td><strong>remove</strong></td><td>移除</td><td><code>The legacy API was removed in v4.0.</code></td></tr><tr><td><strong>compatible / compatibility</strong></td><td>兼容 / 兼容性</td><td><code>This release drops compatibility with Node 14.</code></td></tr><tr><td><strong>breaking change</strong></td><td>破坏性变更</td><td><code>⚠ BREAKING CHANGE: the minimum Node version is now 18.</code>（Conventional Commits）</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">deprecated ≠ removed</p><p><code>deprecated</code>（已废弃）表示<strong>还能用，但不要再用于新代码</strong>；<code>removed</code> 才是&quot;没了&quot;。升级依赖前务必在 Changelog 里区分这两个词。</p></div><h2 id="_1-5-主题组三-团队协作-20-词" tabindex="-1">1.5 主题组三：团队协作（20 词） <a class="header-anchor" href="#_1-5-主题组三-团队协作-20-词" aria-label="Permalink to &quot;1.5 主题组三：团队协作（20 词）&quot;">​</a></h2><p>GitHub 是程序员最大的英语实战场。这 20 个词覆盖 Issue / PR / Review 90% 的日常交流。</p><h3 id="issue-pr-动作词" tabindex="-1">Issue / PR 动作词 <a class="header-anchor" href="#issue-pr-动作词" aria-label="Permalink to &quot;Issue / PR 动作词&quot;">​</a></h3><table tabindex="0"><thead><tr><th>词汇</th><th>释义</th><th>真实语料</th></tr></thead><tbody><tr><td><strong>submit / open</strong></td><td>提交 / 开启（Issue、PR）</td><td><code>I opened an issue to track this.</code></td></tr><tr><td><strong>close</strong></td><td>关闭</td><td><code>Closing this as completed.</code></td></tr><tr><td><strong>merge</strong></td><td>合并</td><td><code>Merged #1024 into main.</code></td></tr><tr><td><strong>review</strong></td><td>审查</td><td><code>Could someone review this PR?</code></td></tr><tr><td><strong>approve</strong></td><td>批准（Review 通过）</td><td><code>Approved with minor comments.</code></td></tr><tr><td><strong>request changes</strong></td><td>要求修改</td><td><code>Requesting changes: tests are missing.</code></td></tr><tr><td><strong>assign</strong></td><td>指派</td><td><code>Assigning to @maintainer-joe.</code></td></tr><tr><td><strong>mention / ping</strong></td><td>@ 提醒</td><td><code>Ping @team-frontend for a look.</code></td></tr><tr><td><strong>fork / clone</strong></td><td>复刻 / 克隆</td><td><code>Fork the repo and open a PR from a branch.</code></td></tr><tr><td><strong>rebase</strong></td><td>变基</td><td><code>Please rebase onto the latest main.</code></td></tr></tbody></table><h3 id="review-评论高频词-缩写必背" tabindex="-1">Review 评论高频词（缩写必背） <a class="header-anchor" href="#review-评论高频词-缩写必背" aria-label="Permalink to &quot;Review 评论高频词（缩写必背）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>词汇/缩写</th><th>全称/释义</th><th>真实语料</th></tr></thead><tbody><tr><td><strong>LGTM</strong></td><td>Looks Good To Me（没问题，可以合）</td><td><code>LGTM, thanks!</code></td></tr><tr><td><strong>nit / nitpick</strong></td><td>小瑕疵（不阻塞合并）</td><td><code>nit: extra blank line here.</code></td></tr><tr><td><strong>PTAL</strong></td><td>Please Take A Look（请看一下）</td><td><code>PTAL when you have time.</code></td></tr><tr><td><strong>WIP</strong></td><td>Work In Progress（进行中，勿合）</td><td><code>[WIP] refactor request layer</code></td></tr><tr><td><strong>TL;DR</strong></td><td>Too Long; Didn&#39;t Read（一句话总结）</td><td><code>TL;DR: this PR cuts bundle size by 30%.</code></td></tr><tr><td><strong>blocker</strong></td><td>阻塞项</td><td><code>This is a blocker for the release.</code></td></tr><tr><td><strong>follow-up</strong></td><td>后续跟进</td><td><code>I&#39;ll address this in a follow-up PR.</code></td></tr><tr><td><strong>off-topic</strong></td><td>跑题</td><td><code>Let&#39;s keep this thread on-topic.</code></td></tr><tr><td><strong>duplicate (dup)</strong></td><td>重复</td><td><code>Duplicate of #512.</code></td></tr><tr><td><strong>stale</strong></td><td>过期（久未活跃）</td><td><code>This issue has been marked as stale.</code></td></tr></tbody></table><h2 id="_1-6-中式英语常见错误" tabindex="-1">1.6 中式英语常见错误 <a class="header-anchor" href="#_1-6-中式英语常见错误" aria-label="Permalink to &quot;1.6 中式英语常见错误&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">❌ 错误 1：逐词翻译</p><p><s><code>This function very usefulness.</code></s>（这个函数很有用。）</p><p>✅ <code>This function is very useful.</code> —— <code>usefulness</code> 是名词，此处需要形容词 <code>useful</code> 作表语。中文&quot;很有用&quot;直接映射容易词性错位。</p></div><div class="danger custom-block"><p class="custom-block-title">❌ 错误 2：滥用 very / very much</p><p><s><code>I very like this API.</code></s></p><p>✅ <code>I really like this API.</code> / <code>I like this API a lot.</code> —— <code>very</code> 不能修饰动词。</p></div><div class="danger custom-block"><p class="custom-block-title">❌ 错误 3：中式客套</p><p><s><code>Please kindly help me review, thank you very much.</code></s></p><p>✅ <code>Could you take a look? Thanks!</code> —— 技术社区的礼貌是<strong>简洁 + 具体</strong>，堆砌敬辞反而显得生疏。</p></div><div class="danger custom-block"><p class="custom-block-title">❌ 错误 4：直译&quot;提个问题&quot;</p><p><s><code>I want to ask a question.</code></s></p><p>✅ 直接问问题本身：<code>Why does X return undefined here?</code> —— Issue/IM 里预告&quot;我要提问&quot;是冗余信息。</p></div><h2 id="_1-7-练习-附答案" tabindex="-1">1.7 练习（附答案） <a class="header-anchor" href="#_1-7-练习-附答案" aria-label="Permalink to &quot;1.7 练习（附答案）&quot;">​</a></h2><h3 id="练习-1-报错拆解" tabindex="-1">练习 1：报错拆解 <a class="header-anchor" href="#练习-1-报错拆解" aria-label="Permalink to &quot;练习 1：报错拆解&quot;">​</a></h3><p>阅读这条真实报错，说出每个部分的含义：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TypeError: Cannot read properties of undefined (reading &#39;map&#39;)</span></span>
<span class="line"><span>    at UserList (/src/components/UserList.jsx:24:18)</span></span></code></pre></div><details><summary>查看答案</summary><ul><li><code>TypeError</code>：错误类型（类型错误）；</li><li><code>Cannot read properties of undefined</code>：试图读取 <code>undefined</code> 的属性；</li><li><code>(reading &#39;map&#39;)</code>：具体读的是 <code>map</code> 属性——即某个变量是 <code>undefined</code>，却对它调用了 <code>.map()</code>；</li><li><code>at UserList (...:24:18)</code>：栈帧，出错位置在 UserList 组件文件第 24 行第 18 列。</li></ul><p><strong>修复方向</strong>：找到第 24 行调用 <code>.map()</code> 的变量，确认它为什么不是数组（数据未加载？接口返回结构变了？）。</p></details><h3 id="练习-2-选词填空" tabindex="-1">练习 2：选词填空 <a class="header-anchor" href="#练习-2-选词填空" aria-label="Permalink to &quot;练习 2：选词填空&quot;">​</a></h3><p>从本章词汇中选择合适的词填空：<code>deprecated</code> / <code>removed</code> / <code>workaround</code> / <code>regression</code></p><blockquote><p>After upgrading to v5, the export feature broke — it worked fine in v4. This is a classic ______. Before the official fix, we can downgrade to v4 as a ______. Also note that the old <code>render()</code> API was ______ in v5 and will be ______ in v6.</p></blockquote><details><summary>查看答案</summary><ol><li><code>regression</code>（回归：旧版本正常的功能在新版本坏掉）；</li><li><code>workaround</code>（临时绕过方案）；</li><li><code>deprecated</code>（v5 中废弃但仍可用）；</li><li><code>removed</code>（v6 才会移除）。</li></ol></details><h3 id="练习-3-改写中式英语" tabindex="-1">练习 3：改写中式英语 <a class="header-anchor" href="#练习-3-改写中式英语" aria-label="Permalink to &quot;练习 3：改写中式英语&quot;">​</a></h3><p>把这句 Review 评论改写成地道的技术英语：</p><blockquote><p>&quot;这个代码 very good，但是 please kindly 把变量名改一下，thank you very much。&quot;</p></blockquote><details><summary>参考答案</summary><blockquote><p><code>LGTM overall. One nit: could you rename this variable to something more descriptive? Thanks!</code></p></blockquote><p>要点：用 <code>nit</code> 标记不阻塞的小问题；请求具体（改成什么方向）；礼貌靠 <code>could you</code> + <code>Thanks</code> 即可。</p></details><h3 id="练习-4-词块翻译-中-→-英" tabindex="-1">练习 4：词块翻译（中 → 英） <a class="header-anchor" href="#练习-4-词块翻译-中-→-英" aria-label="Permalink to &quot;练习 4：词块翻译（中 → 英）&quot;">​</a></h3><ol><li>这个参数是可选的。</li><li>这个函数原地修改了数组。</li><li>我本地复现不了这个问题。</li></ol><details><summary>查看答案</summary><ol><li><code>This parameter is optional.</code></li><li><code>This function mutates the array in place.</code></li><li><code>I can&#39;t reproduce this issue locally.</code></li></ol></details><h3 id="练习-5-缩写速答" tabindex="-1">练习 5：缩写速答 <a class="header-anchor" href="#练习-5-缩写速答" aria-label="Permalink to &quot;练习 5：缩写速答&quot;">​</a></h3><p>在 PR 评论里看到 <code>LGTM, just a nit</code>，这句话是什么意思？合并会受影响吗？</p><details><summary>查看答案</summary><p>意思是&quot;整体看没问题（Looks Good To Me），只有一个小瑕疵&quot;。<code>nit</code> 不阻塞合并——改不改看作者，Reviewer 已经放行。</p></details><h2 id="_1-8-本章小结与下一步" tabindex="-1">1.8 本章小结与下一步 <a class="header-anchor" href="#_1-8-本章小结与下一步" aria-label="Permalink to &quot;1.8 本章小结与下一步&quot;">​</a></h2><ul><li>技术英语的突破口是<strong>词块 + 真实语料 + 主题分组</strong>，不是词表；</li><li>已拿下 60 个最高频词：编程概念 20 + 调试报错 20 + 团队协作 20；</li><li>下一章进入「高频句式与语法」：学会被动语态和祈使句，你就能读懂任何文档的&quot;操作说明&quot;段落。</li></ul><div class="tip custom-block"><p class="custom-block-title">配套漫画</p><p>本话剧情见漫画剧场 <a href="/comics/index.html" target="_blank" rel="noopener">EP.01 技术英语不是学校英语</a>——标签君查字典查到崩溃的那个下午。</p></div>`,65)])])}const p=e(a,[["render",s]]);export{g as __pageData,p as default};
